SELECT 100.0 * (
  SELECT COUNT(*) FROM (
    SELECT DISTINCT molecule_id FROM molecule WHERE label = '+'
  ) c
  WHERE c.molecule_id NOT IN (
    SELECT DISTINCT molecule_id FROM atom WHERE element = 'f'
  )
) / (
  SELECT COUNT(*) FROM (
    SELECT DISTINCT molecule_id FROM molecule WHERE label = '+'
  )
) AS percentage_without_fluorine
